tosedo handle(line)
    sheye chars <- [];
    sheye i <- 0;
    veshim (i < louwo(line)) {
        sheye c <- line[i];
        wesosa (isalnum(c)) {
            wesosa (("A" <= c) dilisyo (c <= "Z")) {
                c <- ramou(lettercode(c) + 32);
            }
            omse(chars, c);
        }
        i <- i + 1;
    }
    sheye ans <- shilsa;
    sheye j <- 0;
    sheye k <- louwo(chars) - 1;
    veshim (j < k) {
        wesosa (chars[j] <> chars[k]) {
            ans <- ishe;
        }
        j <- j + 1;
        k <- k - 1;
    }
    wesosa (ans) {
        wami "yes";
    } oli {
        wami "no";
    }
bawoum tosedo

