    sheye cur <- "";
    sheye i <- 0;
    veshim (i < louwo(line)) {
        wesosa (line[i] = " ") {
            omse(parts, cur);
            cur <- "";
        } oli {
            cur <- cur + line[i];
        }
        i <- i + 1;
    }
    wesosa (cur <> "") {
        omse(parts, cur);
    }
    cha parts;
