        sheye mid <- (lo + hi) / 2;
        wesosa (xs[mid] < q) {
            lo <- mid + 1;
        } oli {
            hi <- mid;
        }
    }
    sheye cnt <- lo;
    sheye found <- ishe;
    wesosa (cnt < louwo(xs)) {
        wesosa (xs[cnt] = q) {
            found <- shilsa;
        }
    }
    wesosa (found) {
        wami cnt + " found";
    } oli {
        wami cnt + " missing";
    }
