    sheye m <- num2(line[5, 6]);
    sheye d <- num2(line[8, 9]);
    wesosa (m <= 2) {
        m <- m + 12;
        y <- y - 1;
    }
    sheye K <- y drossou 100;
    sheye J <- y / 100;
    sheye h <- (d + ((13 * (m + 1)) / 5) + K + (K / 4) + (J / 4) - 2 * J) drossou 7;
